                if !matches!(v0, Value::Bool(false)) { return None; }
                let v1 = heap.call(1, &[args[1]])?; let _ = v1;
                heap.bind(v1, None)?;
                let v2 = heap.call(2, &[args[0], v1])?; let _ = v2;
